import { VoxelLogicType } from "../VoxelLogicType";
export class VoxelLogicPoweredType extends VoxelLogicType {
    init() { }
    run(voxel) {
        return voxel.getPower() > 0;
    }
    *getEffects() {
        for (const effect of this.data.on)
            yield effect;
        for (const effect of this.data.off)
            yield effect;
    }
}
